import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"项目介绍","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md","lastUpdated":0}`),a={name:`guide/introduction.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="项目介绍" tabindex="-1">项目介绍 <a class="header-anchor" href="#项目介绍" aria-label="Permalink to “项目介绍”">​</a></h1><p>Emaki Series 是一组面向 Minecraft 26.1 及以上版本的 RPG 插件. 它不把全部玩法塞进一个插件里: 公共能力都放在 CoreLib, 属性, 装备, 强化, 宝石, 饰品, 等级, 技能, 合成, 烹饪, 图鉴和仓库则各自拆成独立模块, 你想装哪个就装哪个</p><p>举个例子: 你只想给服务器加 RPG 属性, 就只装 CoreLib + Attribute 两个; 想要完整装备线, 再加 Item, Forge, Strengthen, Gem. 用不到的模块可以不装, 互不拖累</p><p>对照下面的能力清单, 你的服务器需要哪几项, 就装哪几个模块:</p><ul><li>装备应该有固定 ID, 名称, Lore, 属性, 套装和技能绑定</li><li>属性系统要能算物理伤害, 法术伤害, 投射物, 暴击, 防御, 穿透, 资源等数值</li><li>装备成长要有锻造, 强化, 宝石, 品质, 材料, 失败惩罚和展示刷新</li><li>玩家成长要有多种等级类型, 经验来源, 升级条件, 排行榜, 以及占位符展示</li><li>技能要有主动释放, 被动触发, 冷却, 资源消耗, 等级参数, 并能对接外部技能引擎</li><li>玩法系统要有世界里的工位, 交互流程, 投料, 产物发放和进度保存</li><li>生产系统要能按配方制作, 合并扣除材料, 排队生产, 产物等玩家领取</li><li>角色外观与加成要有独立于装备栏的饰品槽与饰品套装</li><li>收集与引导要有原版成就页, 节点触发和完成奖励</li><li>所有模块都要能共用动作, GUI, 物品来源, 经济, 数据保存和配置加载这些能力</li></ul><p>后面每个模块都会单独讲清楚配置目录, 命令, 权限, 常用 YAML 字段和验证方式, 你照着配就行</p><h2 id="支持版本" tabindex="-1">支持版本 <a class="header-anchor" href="#支持版本" aria-label="Permalink to “支持版本”">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>要求</th></tr></thead><tbody><tr><td>服务端</td><td>Paper 26.1 及以上 (Folia 也支持)</td></tr><tr><td>Java</td><td><code>25</code></td></tr><tr><td>插件声明的最低接口版本</td><td><code>26.1</code></td></tr><tr><td>构建方式 (自己编译时才需要)</td><td>Gradle 多模块工程, 已固定 Gradle 9.8.0</td></tr></tbody></table><div class="caution custom-block"><p class="custom-block-title custom-block-title-default">CAUTION</p><p>这些插件只面向 Minecraft 26.1 及以上版本开发, 不兼容更低的版本. 插件里声明的最低接口版本是 <code>26.1</code>, 低于这个版本的服务器会被 Paper 直接拒绝加载. 插件同时声明了 Folia 支持</p></div><h2 id="模块一览" tabindex="-1">模块一览 <a class="header-anchor" href="#模块一览" aria-label="Permalink to “模块一览”">​</a></h2><p>你只是下载现成 jar 装来用的话, 表里&quot;归属&quot;一列可以忽略; 它说明的是源码构建: <code>默认</code> 表示每次构建都会编译; <code>私有</code> 表示只有在源码仓库根目录放了一个 <code>.key</code> 文件时才会一起编译</p><table tabindex="0"><thead><tr><th>模块</th><th>版本</th><th>归属</th><th>它能做什么</th></tr></thead><tbody><tr><td>EmakiCoreLib</td><td><code>5.0.0</code></td><td>默认</td><td>公共基础库, 其他所有模块都要靠它</td></tr><tr><td>EmakiAttribute</td><td><code>5.0.0</code></td><td>默认</td><td>属性, 资源, 伤害计算, 条件判断, 属性读写接口</td></tr><tr><td>EmakiForge</td><td><code>5.0.0</code></td><td>默认</td><td>锻造: 图纸要求, 材料投入, 品质与配方书</td></tr><tr><td>EmakiStrengthen</td><td><code>5.0.0</code></td><td>默认</td><td>装备强化: 星级阶段, 保护道具, 失败惩罚与刷新</td></tr><tr><td>EmakiCooking</td><td><code>5.0.0</code></td><td>默认</td><td>世界里的烹饪工位 (砧板, 炒锅等)</td></tr><tr><td>EmakiLevel</td><td><code>2.0.0</code></td><td>默认</td><td>多种等级类型, 经验来源, 升级条件, 排行榜与 MythicMobs 经验掉落</td></tr><tr><td>EmakiCodex</td><td><code>2.0.0</code></td><td>默认</td><td>用原版成就页做的图鉴 GUI, 支持解锁/激活/领取与动作奖励</td></tr><tr><td>EmakiStation</td><td><code>2.0.0</code></td><td>默认</td><td>通用合成工作站: 排队生产, 付费队列位, 独立分解站</td></tr><tr><td>EmakiGem</td><td><code>3.0.0</code></td><td>私有</td><td>宝石: 插槽, 开孔, 镶嵌, 提取与升级</td></tr><tr><td>EmakiSkills</td><td><code>3.0.0</code></td><td>私有</td><td>主动/被动技能: 触发器, 资源消耗, MythicMobs 对接</td></tr><tr><td>EmakiItem</td><td><code>3.0.0</code></td><td>私有</td><td>自定义物品: 两级浏览界面, 套装, 触发器与自动更新</td></tr><tr><td>EmakiStorage</td><td><code>2.0.0</code></td><td>私有</td><td>分页仓库界面, 单格大额存放, 容量档位与付费解锁</td></tr><tr><td>EmakiAccessory</td><td><code>2.0.0</code></td><td>私有</td><td>多页独立饰品栏, 部位槽位, 丢失取回, 饰品套装与属性/技能加成</td></tr><tr><td>EmakiMobs</td><td><code>2.0.0</code></td><td>默认</td><td>自定义生物: 刷新规则, 掉落表与技能行为</td></tr><tr><td>EmakiStructure</td><td><code>1.0.8</code></td><td>私有</td><td>结构模板导出与放置, 多方块机关交互, 生成回滚与家具还原</td></tr><tr><td>EmakiDungeon</td><td><code>1.0.13</code></td><td>默认</td><td>组队副本: 独立实例世界, 挑战限制与难度选择, 奖励暂存结算, 流程门禁与地图编辑器</td></tr></tbody></table><div class="note custom-block"><p class="custom-block-title custom-block-title-default">NOTE</p><p>上面说的&quot;私有&quot;是<strong>源码构建</strong>层面的门控: 源码仓库根目录有 <code>.key</code> 文件时才会把 EmakiSkills, EmakiGem, EmakiItem, EmakiStorage, EmakiStructure, EmakiAccessory 一起编译. 没有 <code>.key</code> 时构建 27 个模块, 有 <code>.key</code> 时构建 33 个. 与&quot;能不能安装使用&quot;无关</p></div><p>除了上面这些服务器插件, 工程里还有各模块的 <code>emaki-*-api</code> 编译期构件. 普通安装用不到它: 它们<strong>不是服务器插件, 不要放进 <code>plugins/</code> 目录</strong> (这一条只对开发插件的服主/开发者有意义)</p><h2 id="为什么需要-corelib" tabindex="-1">为什么需要 CoreLib <a class="header-anchor" href="#为什么需要-corelib" aria-label="Permalink to “为什么需要 CoreLib”">​</a></h2><p>CoreLib 是 Emaki Series 的&quot;公共地基&quot;. 你做配置时迟早会遇到下面这些难题:</p><ul><li>怎么在 YAML 里执行奖励, 发提示, 扣钱, 执行命令, 放粒子, 播音效?</li><li>怎么统一打开 GUI, 处理按钮点击, 保护交互状态?</li><li>怎么识别来自原版, MMOItems, ItemsAdder, Nexo, Oraxen, EcoItems, CraftEngine 等不同来源的物品?</li><li>怎么把各个模块写进去的装备状态都存好, 又互不覆盖?</li><li>怎么把锻造, 强化, 宝石, 物品基础信息组合成最终显示的样子?</li><li>怎么写条件判断, 概率, 延迟动作, 经济扣费?</li></ul><p>如果每个模块都各写一套, 最后会很难维护. CoreLib 把这些公共能力统一起来, 业务模块只管自己的玩法</p><h2 id="常见组合方式" tabindex="-1">常见组合方式 <a class="header-anchor" href="#常见组合方式" aria-label="Permalink to “常见组合方式”">​</a></h2><p>下面按&quot;你想做什么&quot;分组, 每组直接列出要装的模块</p><h3 id="只做属性和战斗" tabindex="-1">只做属性和战斗 <a class="header-anchor" href="#只做属性和战斗" aria-label="Permalink to “只做属性和战斗”">​</a></h3><ol><li>EmakiCoreLib</li><li>EmakiAttribute</li><li>可选: PlaceholderAPI, MythicMobs, MMOItems</li></ol><p>适合: 只想做 RPG 属性, 伤害类型, 资源状态, 占位符展示, 以及和外部怪物技能联动</p><h3 id="做装备成长" tabindex="-1">做装备成长 <a class="header-anchor" href="#做装备成长" aria-label="Permalink to “做装备成长”">​</a></h3><ol><li>EmakiCoreLib</li><li>EmakiAttribute</li><li>EmakiItem</li><li>EmakiForge</li><li>EmakiStrengthen</li><li>EmakiGem</li><li>可选: EmakiAccessory</li></ol><p>适合: 你要做一条完整装备线, 基础装备由 Item 生成, Forge 改造品质, Strengthen 提升星级, Gem 提供插槽与宝石属性, Attribute 负责最终数值计算. 再装上 Accessory, 你就多一条不占装备栏的饰品线</p><h3 id="做等级成长" tabindex="-1">做等级成长 <a class="header-anchor" href="#做等级成长" aria-label="Permalink to “做等级成长”">​</a></h3><ol><li>EmakiCoreLib</li><li>EmakiLevel</li><li>可选: PlaceholderAPI, MythicMobs, EmakiAttribute, EmakiCooking, EmakiForge</li></ol><p>适合: 做主等级, 战斗等级, 采集等级, 生活职业等级等多条成长线, 把经验来源接到原版事件, MythicMobs 掉落或其他 Emaki 插件的动作上</p><h3 id="做技能系统" tabindex="-1">做技能系统 <a class="header-anchor" href="#做技能系统" aria-label="Permalink to “做技能系统”">​</a></h3><ol><li>EmakiCoreLib</li><li>EmakiSkills</li><li>MythicMobs</li><li>可选: EmakiAttribute, PlaceholderAPI, EmakiItem, EmakiLevel</li></ol><p>适合: 让装备, 权限, 等级, 配置或外部来源解锁技能; Skills 负责冷却, 资源消耗和触发, 实际技能效果交给 MythicMobs 执行</p><h3 id="做生活玩法" tabindex="-1">做生活玩法 <a class="header-anchor" href="#做生活玩法" aria-label="Permalink to “做生活玩法”">​</a></h3><ol><li>EmakiCoreLib</li><li>EmakiCooking</li><li>可选: EmakiLevel, CraftEngine, ItemsAdder, Nexo</li></ol><p>适合: 做砧板, 炒锅, 研磨机, 蒸锅这些世界工位, 让玩家通过和方块交互完成烹饪; 想让烹饪也给经验, 可以接 EmakiLevel 或 CoreLib 的动作</p><h3 id="做生产与仓储" tabindex="-1">做生产与仓储 <a class="header-anchor" href="#做生产与仓储" aria-label="Permalink to “做生产与仓储”">​</a></h3><ol><li>EmakiCoreLib</li><li>EmakiStation</li><li>可选: EmakiStorage, EmakiItem, EmakiLevel</li></ol><p>适合: 做按配方排队生产的工作站, 材料可以同时从背包和仓库里取, 产物直接入库, 还能用分解站回收装备. 装了 EmakiStorage 后仓库会参与取材与发货; 不装就只用背包</p><h3 id="做成就图鉴" tabindex="-1">做成就图鉴 <a class="header-anchor" href="#做成就图鉴" aria-label="Permalink to “做成就图鉴”">​</a></h3><ol><li>EmakiCoreLib</li><li>EmakiCodex</li><li>可选: PacketEvents, PlaceholderAPI, MythicMobs</li></ol><p>适合: 用 <code>advancements/*.yml</code> 把玩法目标做成原版成就页, 由击杀, 合成, 钓鱼, 破坏方块等共享事件触发节点, 节点完成时执行动作发奖励. 装了 PacketEvents 还能额外注入成就树坐标</p>`,41)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};